<script setup>
import { uniqueKey } from '../../services/ids.js';
import { reactive,ref,computed,onMounted } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { api } from '../../services/api.js';
import { workspace,loadStores } from '../../services/workspace.js';
import { canFeature } from '../../services/auth.js';
import { notify } from '../../services/notifications.js';
import Icon from '../../components/Icon.vue';
const route=useRoute(),router=useRouter(),editing=computed(()=>!!route.params.id),store=ref(null),loading=ref(true),saving=ref(false),error=ref('');let original='';
const form=reactive({id:uniqueKey(),type:'cash',name:'Efectivo',instructions:'',deliveryIds:[],active:true,bank:{holder:'',bank:'',cbu:'',alias:'',cuit:''}});
const types={cash:'Efectivo',transfer:'Transferencia bancaria',mercadopago:'Mercado Pago · Checkout Pro'};
const allowedTypes=computed(()=>Object.fromEntries(Object.entries(types).filter(([type])=>type!=='mercadopago'||canFeature('payments.mercadopago')||type===form.type)));
const deliveriesEnabled=computed(()=>true);
onMounted(async()=>{try{store.value=await api.get(`/stores/${workspace.activeStoreId}`);if(editing.value){const item=store.value.payments.find(p=>p.id===route.params.id);if(!item)throw new Error('La forma de pago no existe.');original=JSON.stringify(item);Object.assign(form,item);form.bank={holder:'',bank:'',cbu:'',alias:'',cuit:'',...item.bank};}}catch(e){error.value=e.message}finally{loading.value=false}});
async function save(){saving.value=true;error.value='';try{const latest=await api.get(`/stores/${workspace.activeStoreId}`),index=latest.payments.findIndex(p=>p.id===form.id);if(editing.value&&(index<0||JSON.stringify(latest.payments[index])!==original))throw new Error('Esta forma de pago cambió desde que abriste el formulario. Volvé al listado y abrila nuevamente para conservar los cambios más recientes.');const value=JSON.parse(JSON.stringify(form));if(index>=0)latest.payments[index]=value;else latest.payments.push(value);await api.put(`/stores/${workspace.activeStoreId}/payments`,{payments:latest.payments,deliveries:latest.deliveries,expectedUpdatedAt:latest.updatedAt});await loadStores();notify.success('Forma de pago guardada.');router.push('/app/payments?tab=pagos')}catch(e){error.value=e.message;notify.error(e.message)}finally{saving.value=false}}
</script>
<template><div><RouterLink to="/app/payments?tab=pagos" class="p-back-link"><Icon name="back" :size="14"/>Volver a formas de pago</RouterLink><header class="p-page-header"><div><h1>{{editing?'Editar forma de pago':'Nueva forma de pago'}}</h1><p>Definí sus instrucciones y en qué entregas se podrá utilizar.</p></div></header><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><form v-else-if="store" @submit.prevent="save" class="p-form"><section class="p-section-card"><div class="p-section-title"><h2>Datos del medio de pago</h2><Icon name="credit"/></div><div class="p-form-grid"><div class="p-field"><label for="method-type">Tipo de pago</label><select id="method-type" v-model="form.type" @change="form.name=types[form.type]"><option v-for="(label,type) in allowedTypes" :key="type" :value="type">{{label}}</option></select></div><div class="p-field"><label for="method-name">Nombre visible *</label><input id="method-name" v-model.trim="form.name" required maxlength="120"/></div><div class="p-field full"><label for="method-instructions">Instrucciones para el cliente</label><textarea id="method-instructions" v-model="form.instructions" maxlength="4000" rows="4" placeholder="Por ejemplo: abonás al retirar en nuestro local."/></div><label class="p-check"><input v-model="form.active" type="checkbox"/>Habilitar este medio de pago</label></div></section><section v-if="form.type==='transfer'" class="p-section-card"><div class="p-section-title"><h2>Cuenta bancaria</h2></div><div class="p-form-grid"><div class="p-field"><label for="bank-holder">Titular *</label><input id="bank-holder" v-model="form.bank.holder" required maxlength="180"/></div><div class="p-field"><label for="bank-name">Banco / billetera *</label><input id="bank-name" v-model="form.bank.bank" required maxlength="180"/></div><div class="p-field"><label for="bank-cbu">CBU / CVU</label><input id="bank-cbu" v-model.trim="form.bank.cbu" inputmode="numeric" maxlength="22" pattern="[0-9]{22}" :required="!form.bank.alias"/></div><div class="p-field"><label for="bank-alias">Alias</label><input id="bank-alias" v-model.trim="form.bank.alias" maxlength="60" :required="!form.bank.cbu"/></div><div class="p-field"><label for="bank-cuit">CUIT / CUIL</label><input id="bank-cuit" v-model.trim="form.bank.cuit" maxlength="30"/></div></div><div class="p-info">El cliente podrá adjuntar un comprobante después de crear el pedido. Confirmá el pago manualmente desde el detalle cuando verifiques el ingreso.</div></section><section v-if="form.type==='mercadopago'" class="p-section-card"><div class="p-section-title"><h2>Cuenta de Mercado Pago</h2><span class="p-badge" :class="store.integrations?.mercadopago?.hasAccessToken&&store.integrations?.mercadopago?.hasWebhookSecret?'green':'orange'">{{store.integrations?.mercadopago?.hasAccessToken&&store.integrations?.mercadopago?.hasWebhookSecret?'Configurada':'Sin configurar'}}</span></div><p class="p-help">El comprador continuará en Checkout Pro. Para habilitar esta forma de pago, las credenciales de la tienda deben estar configuradas.</p><RouterLink to="/app/payments?tab=mercadopago" class="btn btn-text">Configurar credenciales <Icon name="arrow" :size="14"/></RouterLink></section><section v-if="deliveriesEnabled" class="p-section-card"><div class="p-section-title"><div><h2>Cuándo ofrecerlo</h2><p>Limitá el medio de pago según la entrega elegida.</p></div></div><div class="p-select-list"><label v-for="d in store.deliveries" :key="d.id" class="p-tag-option"><input v-model="form.deliveryIds" :value="d.id" type="checkbox"/>{{d.name}}{{!d.active?' (deshabilitada)':''}}</label></div><p class="p-help" style="margin-top:16px">{{form.deliveryIds.length?'Solo se ofrecerá con las entregas seleccionadas.':'Sin seleccionar: disponible para todas las entregas habilitadas.'}} Para efectivo en local, seleccioná únicamente Retiro.</p><p v-if="!store.deliveries.length" class="p-info">Primero agregá una <RouterLink to="/app/payments/deliveries/new">forma de entrega</RouterLink>.</p></section><footer class="p-form-footer"><small>Los cambios se aplican a nuevas compras.</small><div class="p-form-actions"><RouterLink to="/app/payments?tab=pagos" class="btn btn-secondary">Cancelar</RouterLink><button class="btn btn-primary" :disabled="saving">{{saving?'Guardando...':'Guardar forma de pago'}}</button></div></footer></form></div></template>
